B.aUp=new A.iJ('Bu kullan\u0131m ko\u015fullar\u0131, Koala by evlumba uygulamas\u0131n\u0131 ("Uygulama") kullan\u0131m\u0131n\u0131z\u0131 d\xfczenler. Uygulamay\u0131 kullanarak bu ko\u015fullar\u0131 kabul etmi\u015f say\u0131l\u0131rs\u0131n\u0131z.',null)
B.aUs=new A.iJ("Son g\xfcncelleme: 18 Mart 2026",null)
B.aVK=new A.j5("Hizmet Tan\u0131m\u0131",null)
B.aUl=new A.iJ("Koala, yapay zeka destekli bir mekan analiz uygulamas\u0131d\u0131r. Kullan\u0131c\u0131lar soru foto\u011fraf\u0131 \xe7ekerek ad\u0131m ad\u0131m \xe7\xf6z\xfcm alabilir. Uygulama 9 farkl\u0131 bran\u015fta AI destekli \xf6\u011fretim hizmeti sunar.",null)
B.aVG=new A.j5("Hesap ve Kay\u0131t",null)
B.aRP=new A.eE("Uygulamay\u0131 kullanmak i\xe7in Google veya telefon numaras\u0131 ile hesap olu\u015fturman\u0131z gerekir",null)
B.aRS=new A.eE("Hesap bilgilerinizin do\u011fru ve g\xfcncel olmas\u0131ndan siz sorumlusunuz",null)
B.aRB=new A.eE("Hesab\u0131n\u0131z\u0131n g\xfcvenli\u011finden siz sorumlusunuz",null)
B.aVP=new A.j5("Kredi Sistemi",null)
B.aRz=new A.eE("Her yeni kullan\u0131c\u0131ya 10 \xfccretsiz kredi verilir",null)
B.aRY=new A.eE("Her mekan analizi 1 kredi harcar",null)
B.aRX=new A.eE("Ek kredi uygulama i\xe7i sat\u0131n alma ile edinilebilir",null)
B.aRW=new A.eE("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aVH=new A.j5("Kabul Edilebilir Kullan\u0131m",null)
B.aUi=new A.iJ("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aRV=new A.eE("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
B.aRO=new A.eE("Otomatik botlar veya scraper kullanmak",null)
B.aRR=new A.eE("Uygulamay\u0131 s\u0131nav s\u0131ras\u0131nda kopya \xe7ekmek i\xe7in kullanmak",null)
B.aRL=new A.eE("Yasalara ayk\u0131r\u0131 i\xe7erik g\xf6ndermek",null)
B.aVI=new A.j5("Fikri M\xfclkiyet",null)
B.aUn=new A.iJ("Uygulama ve i\xe7eri\u011fi Evlumba Software'a aittir. AI taraf\u0131ndan \xfcretilen \xe7\xf6z\xfcmler e\u011fitim ama\xe7l\u0131d\u0131r ve do\u011frulu\u011fu garanti edilmez.",null)
B.aVE=new A.j5("Sorumluluk S\u0131n\u0131rlamas\u0131",null)
B.aUw=new A.iJ('Koala bir mekan analiz asistan\u0131d\u0131r, profesyonel i\xe7 mimar\u0131n yerini almaz. AI \xf6nerilerinin do\u011frulu\u011fu garanti edilmez. Uygulama "oldu\u011fu gibi" sunulur.',null)
B.aVM=new A.j5("De\u011fi\u015fiklikler",null)
B.aUo=new A.iJ("Bu ko\u015fullar\u0131 zaman zaman g\xfcncelleyebiliriz. \xd6nemli de\u011fi\u015fikliklerde uygulama i\xe7i bildirim yapaca\u011f\u0131z.",null)
B.aUv=new A.iJ("Kullan\u0131m ko\u015fullar\u0131yla ilgili sorular\u0131n\u0131z i\xe7in:\nE-posta: info@evlumba.com\nWeb: evlumba.com\nGeli\u015ftirici: Evlumba Software",null)
